<?php
/** Idempotent storefront and information page seed. */
defined( 'WP_CLI' ) || exit( 1 );

function kuka_content_page( string $slug, string $title, string $content ): int {
	$existing = get_page_by_path( $slug );
	$data = array( 'post_type' => 'page', 'post_status' => 'publish', 'post_name' => $slug, 'post_title' => $title, 'post_content' => $content );
	if ( $existing ) { $data['ID'] = $existing->ID; }
	$id = $existing ? wp_update_post( $data, true ) : wp_insert_post( $data, true );
	if ( is_wp_error( $id ) ) { WP_CLI::error( $id->get_error_message() ); }
	return (int) $id;
}

$legal_prefix = '[kuka_legal_warning]<h2>Satıcı / veri sorumlusu bilgileri</h2>[kuka_company_details]';
$pages = array(
	'hakkimizda' => array( 'Hakkımızda', '<p>Kuka Island, Akdeniz kıyılarının açıklığını sade formlar ve birlikte yaşaması kolay renklerle yorumlayan bir mayo markasıdır. Bu metin, gerçek kuruluş hikâyesi müşteriden gelene kadar kullanılan özgün ve geçici marka anlatısıdır.</p><h2>Form özgürlüğü</h2><p>Bikini üstü ve altını tek bir takım kalıbına bağlamıyoruz. Farklı beden, renk ve kesimleri bağımsız seçme özgürlüğü; görünüş kadar rahatlığı da kişisel kılar.</p><h2>Ada ritmi</h2><p>Amacımız gösterişli ayrıntılar yerine hareketi izleyen çizgiler, dengeli kapama ve tekrar giyilebilen parçalar sunmak. Üretim yeri, kuruluş yılı veya sertifika iddiası; doğrulanmış müşteri verisi gelmeden yayımlanmaz.</p>' ),
